import{readFileSync,writeFileSync}from'node:fs';import{gunzipSync,gzipSync}from'node:zlib';import{verifySupportInterface}from'./support-interface.mjs';
const input=process.argv[2],output=process.argv[3],worlds=JSON.parse(gunzipSync(readFileSync(input)));const towerUIDs=['landsd/270317:0','landsd/269908:0','landsd/269839:0','landsd/269837:0'],supportUIDs=['landsd/265851:0','landsd/239351:0'];const rows=[];
function geometry(tri){return{position:tri.flat(2),index:Array.from({length:tri.length*3},(_,i)=>i)};}
for(const[mode,w]of Object.entries(worlds)){const support=geometry(supportUIDs.flatMap(uid=>w[uid]));for(const uid of towerUIDs){const g=geometry(w[uid]);let bottom=Infinity;for(let i=1;i<g.position.length;i+=3)bottom=Math.min(bottom,g.position[i]);const proof=verifySupportInterface(g,bottom,support);rows.push({uid,mode,proof});console.log(JSON.stringify({uid,mode,samples:proof.samples,strictContacts:proof.strictContacts,unresolved:proof.unresolved.length,wallIntersections:proof.wallIntersections}));}}
writeFileSync(output,gzipSync(JSON.stringify({rows,fullAcceptance:false,sourceGeometryChanges:0,qualification:'Unmodified canonical interface checks in actual captured coordinate modes. No source-specific interpretation applied.'})));
